<script setup>
import { computed, onMounted, ref } from 'vue'
import { api } from '../api/client'
const loading = ref(true), error = ref(''), activeProject = ref(null), keyword = ref(''), status = ref('ALL'), showTask = ref(false), showProject = ref(false), toast = ref('')
const projects = ref([]), tasks = ref([]), dashboard = ref({ totalTasks: 0, completedTasks: 0, activeTasks: 0, completionRate: 0, myTasks: [] })
const taskForm = ref({ title: '', description: '', priority: 'MEDIUM', assignee: '林小满', dueDate: '' }), projectForm = ref({ name: '', description: '', color: 'blue' })
const columns = [{ key: 'TODO', label: '待处理' }, { key: 'IN_PROGRESS', label: '进行中' }, { key: 'REVIEW', label: '待审核' }, { key: 'DONE', label: '已完成' }]
const currentProject = computed(() => activeProject.value ? projects.value.find(p => p.id === activeProject.value) : null)
const grouped = computed(() => Object.fromEntries(columns.map(c => [c.key, tasks.value.filter(t => t.status === c.key)])))
async function load() { loading.value = true; error.value = ''; try { const [p, d] = await Promise.all([api.projects(), api.dashboard()]); projects.value = p.items; dashboard.value = d; if (!activeProject.value) activeProject.value = projects.value[0]?.id; await loadTasks() } catch (e) { error.value = e.message } finally { loading.value = false } }
async function loadTasks() { const result = await api.tasks({ projectId: activeProject.value, keyword: keyword.value, status: status.value }); tasks.value = result.items }
async function changeStatus(task, next) { try { await api.updateStatus(task.id, next); await load(); notify('任务状态已更新') } catch (e) { notify(e.message) } }
async function createTask() { if (!taskForm.value.title.trim()) return; await api.createTask(activeProject.value, taskForm.value); taskForm.value = { title: '', description: '', priority: 'MEDIUM', assignee: '林小满', dueDate: '' }; showTask.value = false; await load(); notify('任务已创建') }
async function createProject() { if (!projectForm.value.name.trim()) return; const p = await api.createProject(projectForm.value); projectForm.value = { name: '', description: '', color: 'blue' }; showProject.value = false; activeProject.value = p.id; await load(); notify('项目已创建') }
function notify(message) { toast.value = message; setTimeout(() => toast.value = '', 2200) }
onMounted(load)
</script>
<template>
  <div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">TF</span><div><b>TaskFlow</b><small>工作协作台</small></div></div><div class="side-label">工作空间</div><button class="side-link active"><span>⌂</span>总览</button><button class="side-link"><span>▦</span>我的任务 <i>{{ dashboard.myTasks?.length || 0 }}</i></button><div class="side-label project-label">项目 <button @click="showProject=true">＋</button></div><button v-for="project in projects" :key="project.id" class="project-link" :class="{selected: activeProject===project.id}" @click="activeProject=project.id;loadTasks()"><span class="project-dot" :class="project.color"></span>{{ project.name }}<small>{{ project.taskCount }}</small></button><div class="sidebar-bottom"><div class="profile"><span class="avatar">林</span><div><b>林小满</b><small>项目管理员</small></div><span>···</span></div></div></aside><main class="content"><header class="topbar"><div><span class="crumb">工作空间 / 总览</span><h1>早上好，林小满 <span>✦</span></h1><p>把今天最重要的事情，向前推进一点。</p></div><div class="top-actions"><button class="icon-btn">⌕</button><button class="icon-btn">♧<em></em></button><span class="top-avatar">林</span></div></header><section class="metric-grid"><div class="metric-card"><span>全部任务</span><strong>{{ dashboard.totalTasks }}</strong><small>跨 {{ projects.length }} 个项目</small></div><div class="metric-card peach"><span>进行中的任务</span><strong>{{ dashboard.activeTasks }}</strong><small>保持节奏，继续推进</small></div><div class="metric-card lavender"><span>已完成</span><strong>{{ dashboard.completedTasks }}</strong><small>完成率 {{ dashboard.completionRate }}%</small></div><div class="metric-card dark"><span>本周专注</span><strong>18.5<span>h</span></strong><small>比上周多 12%</small></div></section><section class="workspace-head"><div><span class="kicker">PROJECT / {{ currentProject?.key || '—' }}</span><h2>{{ currentProject?.name || '选择一个项目' }}</h2><p>{{ currentProject?.description }}</p></div><div class="workspace-actions"><button class="btn ghost" @click="showProject=true">新建项目</button><button class="btn primary" @click="showTask=true">＋ 新建任务</button></div></section><section class="toolbar"><div class="search"><span>⌕</span><input v-model="keyword" @input="loadTasks" placeholder="搜索任务..." /></div><div class="filters"><button v-for="item in [{key:'ALL',label:'全部'},{key:'TODO',label:'待处理'},{key:'IN_PROGRESS',label:'进行中'},{key:'REVIEW',label:'待审核'},{key:'DONE',label:'已完成'}]" :key="item.key" :class="{selected: status===item.key}" @click="status=item.key;loadTasks()">{{ item.label }}</button></div></section><div v-if="loading" class="empty">正在加载工作台…</div><div v-else-if="error" class="empty error">{{ error }}<button @click="load">重试</button></div><section v-else class="board"><div v-for="column in columns" :key="column.key" class="column"><div class="column-head"><span class="status-dot" :class="column.key.toLowerCase()"></span><b>{{ column.label }}</b><small>{{ grouped[column.key].length }}</small><span>···</span></div><article v-for="task in grouped[column.key]" :key="task.id" class="task-card"><div class="task-top"><span class="priority" :class="task.priority.toLowerCase()">{{ task.priority==='HIGH'?'高':task.priority==='LOW'?'低':'中' }}</span><span class="task-id">TF-{{ String(task.id).padStart(3,'0') }}</span></div><h3>{{ task.title }}</h3><p>{{ task.description }}</p><div class="task-meta"><span>◷ {{ task.dueDate }}</span><span class="assignee">{{ task.assignee?.slice(0,1) }}</span></div><select :value="task.status" @change="changeStatus(task,$event.target.value)"><option v-for="item in columns" :value="item.key" :key="item.key">移动到：{{ item.label }}</option></select></article><button v-if="column.key==='TODO'" class="add-card" @click="showTask=true">＋ 添加任务</button></div></section></main><div v-if="showTask || showProject" class="modal-layer" @click.self="showTask=false;showProject=false"><form v-if="showTask" class="modal" @submit.prevent="createTask"><button type="button" class="close" @click="showTask=false">×</button><span class="kicker">NEW TASK</span><h2>创建任务</h2><input v-model="taskForm.title" required placeholder="任务标题"/><textarea v-model="taskForm.description" rows="3" placeholder="描述一下要完成什么"></textarea><div class="form-row"><select v-model="taskForm.priority"><option value="HIGH">高优先级</option><option value="MEDIUM">中优先级</option><option value="LOW">低优先级</option></select><input v-model="taskForm.dueDate" type="date"/></div><button class="btn primary full">创建任务</button></form><form v-else class="modal" @submit.prevent="createProject"><button type="button" class="close" @click="showProject=false">×</button><span class="kicker">NEW PROJECT</span><h2>创建项目</h2><input v-model="projectForm.name" required placeholder="项目名称"/><textarea v-model="projectForm.description" rows="3" placeholder="项目目标和描述"></textarea><button class="btn primary full">创建项目</button></form></div><div v-if="toast" class="toast">{{ toast }}</div></div>
</template>
